-- Billing set, 0005: the ledger's Postgres tables (outbox plan Task 10, "Ledger tables"; ledger design
-- §5, L-10), after 0004_outbox (G-1) on the billing lane. Generated by drizzle-kit, then hand-edited
-- into the plan's order: CREATE -> distribution (tenant tables only) -> index -> RLS -> grants ->
-- policies, one statement each (with local execution off, Citus builds the shards over new
-- connections, so each statement commits before the next).
-- ledger_accounts, ledger_entry_refs and ledger_discrepancies are distributed by tenant_id inline,
-- colocated with app.tenant_colocation; ledger_reconciliation_runs and ledger_trusted_state are
-- coordinator-local (no distribution call). No FK: a distributed table cannot reference a
-- coordinator-local one, so payment_id, run_id and resolves_id are plain columns.
-- All five have forced RLS. app_runtime inserts its own tenant's rows (never the nil
-- PLATFORM_TENANT_ID: app.tenant_id() is never nil) and reads the tenant tables only when elevated;
-- it gets nothing on the local tables. app_system (BYPASSRLS) reads and inserts every tenant table
-- (the platform rows, the cross-tenant reconciliation) and also updates the local ones. Neither app
-- role has UPDATE or DELETE on a tenant table: entry refs and discrepancies are append-only.
CREATE TABLE "billing"."ledger_accounts" (
	"tenant_id" uuid NOT NULL,
	"code" text NOT NULL,
	"currency" text NOT NULL,
	"immudb_account_id" uuid NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ledger_accounts_tenant_id_code_currency_pk" PRIMARY KEY("tenant_id","code","currency")
);
--> statement-breakpoint
SELECT app.distribute_by_tenant('billing.ledger_accounts');--> statement-breakpoint
CREATE TABLE "billing"."ledger_entry_refs" (
	"tenant_id" uuid NOT NULL,
	"entry_id" uuid NOT NULL,
	"source_key" text NOT NULL,
	"payload_hash" text NOT NULL,
	"immudb_tx_id" bigint,
	"payment_id" uuid,
	"kind" text NOT NULL,
	"posted_at" timestamp (3) with time zone NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ledger_entry_refs_tenant_id_entry_id_pk" PRIMARY KEY("tenant_id","entry_id")
);
--> statement-breakpoint
SELECT app.distribute_by_tenant('billing.ledger_entry_refs');--> statement-breakpoint
CREATE TABLE "billing"."ledger_discrepancies" (
	"tenant_id" uuid NOT NULL,
	"id" uuid NOT NULL,
	"kind" text NOT NULL,
	"source_key" text NOT NULL,
	"expected" jsonb NOT NULL,
	"actual" jsonb NOT NULL,
	"detected_by" text NOT NULL,
	"run_id" uuid,
	"resolves_id" uuid,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ledger_discrepancies_tenant_id_id_pk" PRIMARY KEY("tenant_id","id")
);
--> statement-breakpoint
SELECT app.distribute_by_tenant('billing.ledger_discrepancies');--> statement-breakpoint
CREATE TABLE "billing"."ledger_reconciliation_runs" (
	"id" uuid NOT NULL,
	"from_ts" timestamp (3) with time zone NOT NULL,
	"to_ts" timestamp (3) with time zone NOT NULL,
	"status" text NOT NULL,
	"counts" jsonb NOT NULL,
	"finished_at" timestamp (3) with time zone,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ledger_reconciliation_runs_id_pk" PRIMARY KEY("id")
);
--> statement-breakpoint
CREATE TABLE "billing"."ledger_trusted_state" (
	"database" text NOT NULL,
	"tx_id" bigint NOT NULL,
	"tx_hash" bytea NOT NULL,
	"verified_at" timestamp (3) with time zone NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ledger_trusted_state_database_pk" PRIMARY KEY("database")
);
--> statement-breakpoint
CREATE INDEX "ledger_entry_refs_posted_at_idx" ON "billing"."ledger_entry_refs" USING btree ("posted_at");--> statement-breakpoint
