-- Reads need elevation (the consumer's `roles: []` principal never has it); inserts only the own
-- tenant. No UPDATE or DELETE policy (and no grant): denied.
CREATE POLICY "ledger_accounts_select" ON "billing"."ledger_accounts" FOR SELECT TO app_runtime USING (tenant_id = app.tenant_id() AND app.elevated());--> statement-breakpoint
CREATE POLICY "ledger_accounts_insert" ON "billing"."ledger_accounts" FOR INSERT TO app_runtime WITH CHECK (tenant_id = app.tenant_id());--> statement-breakpoint
CREATE POLICY "ledger_entry_refs_select" ON "billing"."ledger_entry_refs" FOR SELECT TO app_runtime USING (tenant_id = app.tenant_id() AND app.elevated());--> statement-breakpoint
CREATE POLICY "ledger_entry_refs_insert" ON "billing"."ledger_entry_refs" FOR INSERT TO app_runtime WITH CHECK (tenant_id = app.tenant_id());--> statement-breakpoint
CREATE POLICY "ledger_discrepancies_select" ON "billing"."ledger_discrepancies" FOR SELECT TO app_runtime USING (tenant_id = app.tenant_id() AND app.elevated());--> statement-breakpoint
CREATE POLICY "ledger_discrepancies_insert" ON "billing"."ledger_discrepancies" FOR INSERT TO app_runtime WITH CHECK (tenant_id = app.tenant_id());
